package kr.memorynotes;
import org.json.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class PdfFullBackupTest {
 static int checks;
 static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 interface Action{void run()throws Exception;}
 static void rejects(Action action,String message)throws Exception{boolean failed=false;try{action.run();}catch(Exception expected){failed=true;}check(failed,message);}
 static Object call(String name,Class<?>[] types,Object...values)throws Exception{Method m=PdfFullBackup.class.getDeclaredMethod(name,types);m.setAccessible(true);try{return m.invoke(null,values);}catch(InvocationTargetException e){if(e.getCause() instanceof Exception)throw (Exception)e.getCause();throw e;}}
 static byte[] zip(String name,byte[] content)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){z.putNextEntry(new ZipEntry(name));z.write(content);z.closeEntry();}return out.toByteArray();}
 static JSONObject snapshot(String body)throws Exception{JSONObject n=new JSONObject().put("id","note1").put("body",body).put("images",new JSONArray().put(new JSONObject().put("file","11111111-1111-1111-1111-111111111111.img").put("masks",new JSONArray())));return new JSONObject().put("version",1).put("subjects",new JSONArray()).put("chapters",new JSONArray()).put("history",new JSONArray()).put("notes",new JSONArray().put(new JSONObject().put("id","note1").put("data",n.toString())));}
 public static void main(String[] args)throws Exception{
  for(String name:new String[]{"../x","pdf/../../x.pdf","pdf/x/y.pdf","pdf/..\\x.pdf","/pdf/x.pdf","pdf/x.pdf/child","images/a.img","pdf/x-0.ink.json/child"}){final String bad=name;rejects(()->PdfArchiveRules.limit(bad),"reject path "+name);}
  check(PdfArchiveRules.limit("pdf/doc-1.pdf")>=400L*1024*1024,"400MB document allowed");check(PdfArchiveRules.limit("pdf/doc-1-20.ink.json")==PdfArchiveRules.INK,"ink allowed");
  PdfArchiveRules.Budget budget=new PdfArchiveRules.Budget();budget.entry("notes.zip",false);rejects(()->budget.entry("notes.zip",false),"duplicate entry");rejects(()->new PdfArchiveRules.Budget().entry("pdf/a.pdf",true),"directory entry");budget.bytes(PdfArchiveRules.TOTAL);rejects(()->budget.bytes(1),"total bound");
  final long large=400L*1024*1024;InputStream generated=new InputStream(){long left=large;public int read(){if(left==0)return -1;left--;return 0;}public int read(byte[] b,int off,int len){if(left==0)return -1;int n=(int)Math.min(left,len);left-=n;return n;}};final long[] written={0};OutputStream count=new OutputStream(){public void write(int n){written[0]++;}public void write(byte[] b,int off,int len){written[0]+=len;}};
  long copied=(Long)call("copy",new Class<?>[]{InputStream.class,OutputStream.class,long.class,PdfArchiveRules.Budget.class},generated,count,PdfArchiveRules.PDF,new PdfArchiveRules.Budget());check(copied==large&&written[0]==large,"400MB copied with bounded buffer");
  File stage=Files.createTempDirectory("pdf-backup-test-").toFile();try{rejects(()->call("extract",new Class<?>[]{InputStream.class,File.class},new ByteArrayInputStream(zip("../escape.pdf",new byte[]{1})),stage),"archive traversal");check(!new File(stage.getParentFile(),"escape.pdf").exists(),"nothing escaped");
   Set<?> extracted=(Set<?>)call("extract",new Class<?>[]{InputStream.class,File.class},new ByteArrayInputStream(zip("pdf/document.pdf",new byte[]{1,2,3})),stage);check(extracted.contains("pdf/document.pdf")&&new File(stage,"pdf/document.pdf").length()==3,"archive staged");
   byte[] broken=zip("pdf/document.pdf",new byte[100000]);broken=Arrays.copyOf(broken,50);final byte[] cut=broken;rejects(()->call("extract",new Class<?>[]{InputStream.class,File.class},new ByteArrayInputStream(cut),stage),"truncated payload");
  }finally{delete(stage);}
  String marker=InlineImageText.marker("11111111-1111-1111-1111-111111111111.img");JSONObject snap=snapshot(marker);JSONObject inkNote=new JSONObject(snap.getJSONArray("notes").getJSONObject(0).getString("data"));inkNote.put("ink",new JSONArray().put(new JSONObject().put("key","image:11111111-1111-1111-1111-111111111111.img").put("scope","detail")).put(new JSONObject().put("key","body").put("scope","editor")));snap.getJSONArray("notes").getJSONObject(0).put("data",inkNote.toString());PdfFullBackup.validateReferences(snap);rejects(()->PdfFullBackup.validateReferences(snapshot(InlineImageText.marker("33333333-3333-3333-3333-333333333333.img"))),"missing inline image rejected");
  JSONObject clip=new JSONObject().put("file","11111111-1111-1111-1111-111111111111.img").put("role",0).put("doc","doc1").put("page",0);JSONObject state=new JSONObject().put("docs",new JSONArray().put(new JSONObject().put("id","doc1").put("current","note1"))).put("notes",new JSONObject().put("note1",new JSONObject().put("doc","doc1").put("clips",new JSONArray().put(clip))));
  Map<String,String> mapping=new HashMap<String,String>();mapping.put("11111111-1111-1111-1111-111111111111.img","22222222-2222-2222-2222-222222222222.img");call("remap",new Class<?>[]{JSONObject.class,JSONObject.class,Map.class},snap,state,mapping);JSONObject restored=new JSONObject(snap.getJSONArray("notes").getJSONObject(0).getString("data"));check(restored.getJSONArray("images").getJSONObject(0).getString("file").equals("22222222-2222-2222-2222-222222222222.img"),"image record remapped");check(restored.getString("body").equals(InlineImageText.marker("22222222-2222-2222-2222-222222222222.img")),"body marker remapped");check(clip.getString("file").equals("22222222-2222-2222-2222-222222222222.img"),"PDF clip uses same remap");check(restored.getJSONArray("ink").getJSONObject(0).getString("key").equals("image:22222222-2222-2222-2222-222222222222.img"),"image handwriting anchor remapped");check(restored.getJSONArray("ink").getJSONObject(1).getString("key").equals("body"),"body handwriting anchor retained");check(restored.getJSONArray("ink").getJSONObject(0).getString("scope").equals("detail"),"handwriting scope retained");
  PdfFullBackup.verifySnapshot(snap,new JSONObject(snap.toString()));JSONObject changed=new JSONObject(snap.toString());changed.put("notes",new JSONArray());rejects(()->PdfFullBackup.verifySnapshot(snap,changed),"postrestore verification catches dropped rows");
  JSONObject stale=new JSONObject().put("docs",new JSONArray().put(new JSONObject().put("id","doc1").put("current","deleted"))).put("notes",new JSONObject().put("deleted",new JSONObject().put("clips",new JSONArray())).put("note1",new JSONObject().put("doc","gone").put("clips",new JSONArray().put(new JSONObject().put("doc","gone").put("file","11111111-1111-1111-1111-111111111111.img")).put(new JSONObject().put("doc","doc1").put("file","11111111-1111-1111-1111-111111111111.img")))));
  call("pruneOrphans",new Class<?>[]{JSONObject.class,JSONObject.class},stale,snapshot(marker));check(!stale.getJSONObject("notes").has("deleted"),"orphan note mapping removed");check(stale.getJSONObject("notes").getJSONObject("note1").getString("doc").equals("doc1"),"primary doc follows surviving clip");check(stale.getJSONArray("docs").getJSONObject(0).getString("current").isEmpty(),"deleted current note cleared");
  JSONObject ink=new JSONObject().put("version",1).put("strokes",new JSONArray().put(new JSONObject().put("color",-1).put("width",0.01).put("points",new JSONArray().put(0).put(0).put(1).put(1))));PdfFullBackup.validateInkData(ink);checks++;
  JSONObject badInk=new JSONObject(ink.toString());badInk.getJSONArray("strokes").getJSONObject(0).put("width",0);rejects(()->PdfFullBackup.validateInkData(badInk),"zero width ink rejected");
  JSONObject badPoints=new JSONObject(ink.toString());badPoints.getJSONArray("strokes").getJSONObject(0).put("points",new JSONArray().put(0).put(0).put(0.5));rejects(()->PdfFullBackup.validateInkData(badPoints),"odd point count rejected");
  JSONObject outside=new JSONObject(ink.toString());outside.getJSONArray("strokes").getJSONObject(0).put("points",new JSONArray().put(0).put(1.01));rejects(()->PdfFullBackup.validateInkData(outside),"out of page ink rejected");
  System.out.println("PASS: "+checks+" full-backup path, streaming, archive, image mapping, metadata pruning, ink and commit verification checks");
 }
 static void delete(File f){File[] children=f.listFiles();if(children!=null)for(File c:children)delete(c);f.delete();}
}
